CREATE TABLE IF NOT EXISTS `nf_food_data_sources` (
  `id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
  `public_id` text NOT NULL,
  `code` text NOT NULL,
  `version` text NOT NULL,
  `name` text NOT NULL,
  `source_url` text NOT NULL,
  `file_sha256` text,
  `usage_status` text NOT NULL,
  `terms_note` text NOT NULL,
  `imported_at` text,
  `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS `nf_food_data_sources_public_id_unique` ON `nf_food_data_sources` (`public_id`);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS `nf_food_data_sources_code_version_unique` ON `nf_food_data_sources` (`code`,`version`);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS `nf_food_categories` (
  `id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
  `code` text NOT NULL,
  `label` text NOT NULL,
  `source_group` text,
  `sort_order` integer NOT NULL,
  `status` text DEFAULT 'active' NOT NULL,
  `created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS `nf_food_categories_code_unique` ON `nf_food_categories` (`code`);
--> statement-breakpoint
